pub fn prime_num(n: u64) -> bool {
    // Handle the only even prime
    if n == 2 {
        return true;
    }
    // Exclude other even numbers
    if n % 2 == 0 {
        return false;
    }

    // Test odd divisors up to sqrt(n) by checking i <= n / i
    let mut i = 3;
    while i <= n / i {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }

    true
}

